"""Command-line entry point: python3 -m proto_migrate --selftest."""

from __future__ import annotations

import sys

from . import CURRENT_VERSION, VERSIONS, dumps, loads, migrate, run_cli
from .group_migration import run_group_cli
from .linked_migration import run_linked_cli
from .rehearsal import run_rehearse_cli
from .compaction import run_compact_cli


def _selftest():
    assert VERSIONS == (1, 2, 3)
    assert CURRENT_VERSION == 3

    record = {
        "order_id": "A-1",
        "amount": 9.5,
        "status": "new",
        "note": "hi",
        "updated_at": 7,
    }
    blob = dumps(record)
    assert blob.endswith(b"\n") and b" " not in blob
    decoded = loads(blob)
    assert decoded == {"v": 3, **record}

    v1 = loads(b'{"v":1,"order_id":"A-1","amount":9.5,"tags":["x"]}\n')
    assert v1 == {"v": 1, "order_id": "A-1", "amount": 9.5, "tags": ["x"]}
    v2 = migrate(v1, 2)
    assert v2 == {
        "v": 2,
        "order_id": "A-1",
        "amount": 9.5,
        "tags": ["x"],
        "status": "new",
    }
    v3 = migrate(v2, 3)
    assert v3 == {
        "v": 3,
        "order_id": "A-1",
        "amount": 9.5,
        "status": "new",
        "note": "",
        "updated_at": 0,
    }
    assert migrate(v3, 1) == {
        "v": 1,
        "order_id": "A-1",
        "amount": 9.5,
        "tags": [],
    }

    assert loads(dumps({**record, "amount": -0.0}))["amount"] == -0.0
    assert b"-0.0" in dumps({**record, "amount": -0.0})

    for bad_call in (
        lambda: dumps({"v": 3, **record}),
        lambda: dumps(["not", "a", "mapping"]),
        lambda: dumps({**record, "amount": float("nan")}),
        lambda: dumps({**record, "amount": float("inf")}),
        lambda: loads(b'{"v":4,"order_id":"x","amount":1}'),
        lambda: loads(b'{"v":"3"}'),
        lambda: loads(b"not json"),
        lambda: loads(b'{"v":3,"order_id":"x"}'),
        lambda: migrate({"v": 3, **record}, 9),
    ):
        try:
            bad_call()
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError")

    for bad_type_call in (
        lambda: loads("not bytes"),
        lambda: migrate(["not", "a", "mapping"], 3),
        lambda: migrate(record, 3),
    ):
        try:
            bad_type_call()
        except TypeError:
            pass
        else:
            raise AssertionError("expected TypeError")


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["--selftest"]:
        _selftest()
        print("ok")
        return 0
    if args and args[0] == "migrate-log":
        return run_cli(args[1:])
    if args and args[0] == "migrate-logs":
        return run_group_cli(args[1:])
    if args and args[0] == "migrate-linked-logs":
        return run_linked_cli(args[1:])
    if args and args[0] == "rehearse-linked-logs":
        return run_rehearse_cli(args[1:])
    if args and args[0] == "compact-linked-logs":
        return run_compact_cli(args[1:])
    print(
        "usage: python3 -m proto_migrate --selftest\n"
        "       python3 -m proto_migrate migrate-log FILE [--strict|--skip]\n"
        "       python3 -m proto_migrate migrate-logs FILE [FILE ...] "
        "[--strict|--skip]\n"
        "       python3 -m proto_migrate migrate-linked-logs "
        "--group FILE [FILE ...] [--group ...] "
        "[--link SRC:DST:SRC_FIELD:DST_FIELD] [--strict|--skip]\n"
        "       python3 -m proto_migrate rehearse-linked-logs "
        "--group FILE [FILE ...] [--group ...] "
        "[--link SRC:DST:SRC_FIELD:DST_FIELD] [--strict|--skip]\n"
        "       python3 -m proto_migrate compact-linked-logs "
        "--group FILE [FILE ...] [--group ...] "
        "[--link SRC:DST:SRC_FIELD:DST_FIELD] [--strict|--skip]",
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

import io
import json
import os
import subprocess
import sys
import tempfile
import threading
import time
import unittest

import proto_migrate
from proto_migrate import CURRENT_VERSION, dumps
from proto_migrate.log_migration import (
    EXIT_BAD_RECORD,
    EXIT_OK,
    EXIT_USAGE,
    BadRecordError,
    migrate_log_file,
)

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def v1(order_id, amount=1.0):
    return (
        b'{"v":1,"order_id":'
        + json.dumps(order_id).encode()
        + b',"amount":'
        + repr(amount).encode()
        + b',"tags":[]}\n'
    )


def v2(order_id, status="paid"):
    return (
        b'{"v":2,"order_id":'
        + json.dumps(order_id).encode()
        + b',"amount":2.5,"tags":["t"],"status":'
        + json.dumps(status).encode()
        + b"}\n"
    )


def v3(order_id, amount=3.0, status="paid", note="", updated_at=0):
    return dumps(
        {
            "order_id": order_id,
            "amount": amount,
            "status": status,
            "note": note,
            "updated_at": updated_at,
        }
    )


def read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def versions_of(blob):
    return [json.loads(line)["v"] for line in blob.splitlines() if line]


def versions_lenient(blob):
    """Like versions_of but ignores a torn final line from a live append."""
    out = []
    for line in blob.splitlines():
        try:
            out.append(json.loads(line)["v"])
        except (ValueError, KeyError):
            pass
    return out


class TestBasicMigration(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.tmp.name, "log.jsonl")

    def tearDown(self):
        self.tmp.cleanup()

    def test_mixed_versions_all_become_current(self):
        data = v1("A") + v2("B") + v3("C", note="n")
        with open(self.path, "wb") as f:
            f.write(data)
        result = migrate_log_file(self.path, quiesce=0.01)
        self.assertTrue(result.replaced)
        blob = read_bytes(self.path)
        records = [json.loads(line) for line in blob.splitlines()]
        self.assertEqual([r["v"] for r in records], [3, 3, 3])
        self.assertEqual(records[0], {
            "v": 3, "order_id": "A", "amount": 1.0,
            "status": "new", "note": "", "updated_at": 0,
        })
        self.assertEqual(records[1]["status"], "paid")
        self.assertNotIn("tags", records[1])
        self.assertEqual(records[2]["note"], "n")
        # Every output line is canonical dumps output.
        for r in records:
            self.assertEqual(
                dumps({k: val for k, val in r.items() if k != "v"}),
                (json.dumps(r, separators=(",", ":"), ensure_ascii=True) + "\n")
                .encode(),
            )

    def test_negative_zero_preserved(self):
        with open(self.path, "wb") as f:
            f.write(v3("Z", amount=-0.0))
        migrate_log_file(self.path, quiesce=0.01)
        blob = read_bytes(self.path)
        self.assertIn(b"-0.0", blob)

    def test_last_line_without_newline_still_migrated(self):
        with open(self.path, "wb") as f:
            f.write(v1("A"))
            f.write(v1("B")[:-1])  # no trailing newline
        result = migrate_log_file(self.path, quiesce=0.02)
        self.assertTrue(result.replaced)

