def _project_index_keys(proj, dst_links):
    return {field: proj[field] for _lid, field in dst_links
            if field in proj}


def _member_ledger_updates(member, dst_fields_links, salvage_good,
                           salvage_bad):
    """New ledger records for one member, from its line index (no rescan).

    Returns ``{"good": [(global_lineno, {field: value})],
               "bad": [(kind, {field: value})]}`` covering the suffix
    rows that survive plus the bad rows (their target keys keep
    classifying later references) and the post-commit salvaged rows.
    Rows dropped for bad references are excluded from the targets on
    purpose: they are absent from the committed file, so a later
    reference to their key is dangling, exactly as a full rerun sees.
    """
    good, bad = [], []
    for j, _off, kind, proj in _stream_line_entries(member.member_dir):
        keys = _project_index_keys(proj, dst_fields_links)
        if kind == LINE_GOOD:
            if j in member.dropped_local:
                continue
            good.append((member.base_line + j, keys))
        else:
            bad.append((kind, keys))
    n = member.base_line + sum(1 for _j, _o, k, _p
                               in _stream_line_entries(member.member_dir)
                               if k == LINE_GOOD)
    for obj in salvage_good:
        keys = {field: obj[field] for _lid, field in dst_fields_links
                if field in obj}
        good.append((n, keys))
        n += 1
    for kind, keys in salvage_bad:
        bad.append((kind, keys))
    return {"good": good, "bad": bad}


def _publish_ledger(group_dir, groups, links, on_bad, paths, dst_links,
                    old_bases, updates):
    """Publish the next ledger by extending the previous one.

    The reconciled prefix's target records are reused verbatim (the
    prefix is never decoded again); only the suffix updates and the
    committed file metadata are folded in.  The byte prefix length, line
    count and digest come from the file directly (a newline count, not a
    decode).  *updates* maps path to ``{"good": [(lineno, keys)],
    "bad": [(kind, keys)]}``.
    """
    gi_by_path = {}
    for gi, group in enumerate(groups):
        for path in group:
            gi_by_path[os.path.abspath(path)] = gi
    entries = {}
    for path in paths:
        ap = os.path.abspath(path)
        gi = gi_by_path[ap]
        old = old_bases.get(path) or _empty_baseline()
        with open(path, "rb") as f:
            blob = f.read()
        prefix_len = _complete_prefix_len(blob)
        new_line_count = blob[old["offset"]:prefix_len].count(b"\n") \
            if prefix_len >= old["offset"] else 0
        upd = updates.get(path) or {"good": [], "bad": []}
        entries[ap] = {
            "inode": os.stat(path).st_ino,
            "offset": prefix_len,
            "lines": old["lines"] + new_line_count,
            "prefix_sha256": hashlib.sha256(blob[:prefix_len]).hexdigest(),
            "good": list(old["good"]) + list(upd["good"]),
            "skipped": list(old["skipped"]) + [
                {"lineno": -1, "keys": keys}
                for kind, keys in upd["bad"]
                if kind != LINE_BAD_VERSION],
            "badv": list(old["badv"]) + [
                {"lineno": -1, "keys": keys}
                for kind, keys in upd["bad"]
                if kind == LINE_BAD_VERSION],
        }
    ledger = {
        "version": 1,
        "on_bad": on_bad,
        "groups": [[os.path.abspath(p) for p in g] for g in groups],
        "links": [list(l) for l in links],
        "members": entries,
    }
    _write_json_atomic(_ledger_path(group_dir), ledger)

