    canonical, so this is the complete good-record set of the next
    baseline.  Historical skipped / illegal-version target keys are
    carried forward by the caller.
    """
    from . import loads

    good = []
    with open(path, "rb") as f:
        lineno = 0
        while True:
            raw = f.readline()
            if not raw.endswith(b"\n"):
